// Generator entry point for the benchmark half of a catalog case: the admin review
// task in data/tasks.json. The e2e half (scenario + prompt + fixture stub) is
// generated by tools/e2e/gen-catalog.ts, which ships with main; both read the same
// cases from test_data/e2e_catalog. Idempotent: an unchanged case produces no diff.
// `--check` reports drift for CI.
//
// usage: tsx scripts/catalog/gen-tasks.ts (--all | <id>...) [--check] [--dry-run]
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { loadCases } from "../../../tools/e2e/lib/case";
import { emitTasks } from "./lib/emit-task";

interface Args {
  ids: string[];
  all: boolean;
  check: boolean;
  dryRun: boolean;
}

function parseArgs(argv: string[]): Args {
  const args: Args = { ids: [], all: false, check: false, dryRun: false };
  for (const a of argv) {
    if (a === "--all") args.all = true;
    else if (a === "--check") args.check = true;
    else if (a === "--dry-run") args.dryRun = true;
    else if (a.startsWith("--")) throw new Error(`unknown flag: ${a}`);
    else args.ids.push(a);
  }
  return args;
}

async function main(): Promise<void> {
  const args = parseArgs(process.argv.slice(2));
  if (!args.all && args.ids.length === 0) {
    console.error("usage: gen-tasks (--all | <id>...) [--check] [--dry-run]");
    process.exit(2);
  }

  const scriptDir = dirname(fileURLToPath(import.meta.url)); // benchmark/scripts/catalog
  const benchmarkDir = join(scriptDir, "..", "..");
  const catalogDir = join(benchmarkDir, "..", "test_data", "e2e_catalog");
  const now = new Date().toISOString();

  const loaded = await loadCases(catalogDir, args.all ? undefined : args.ids);
  if (loaded.length === 0) {
    console.error(`no cases found under ${catalogDir}`);
    process.exit(1);
  }

  const result = await emitTasks({
    benchmarkDir,
    loaded,
    now,
    check: args.check,
    dryRun: args.dryRun,
  });

  const tag = !result.changed
    ? "ok"
    : args.check
      ? "DRIFT"
      : args.dryRun
        ? "would-write"
        : "wrote";
  console.error(`  ${tag}: ${result.path}`);
  console.error(`\n${loaded.length} case(s); ${result.changed ? 1 : 0} file(s) affected.`);

  if (args.check && result.changed) {
    console.error("tasks.json is out of sync - run `npm run gen-catalog -- --all` and commit.");
    process.exit(1);
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
